L3_1.m_Pos = "L"
L3_1.m_Talk_KOREA = "나오님, 괜찮으신가요? 아까부터 안색이 좋지 않으십니다만."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "ナオ様、大丈夫ですか？　さっきから顔色がよくありませんが。"
L3_1.m_Talk_ENG = "Are you okay, Miss Nao? You do not look so well."
L3_1.m_Talk_TWN = "奈緒，你還好嗎？你從剛才就臉色不太好？"
L3_1.m_Talk_THA = "เป็นอะไรรึเปล่าคะคุณนาโอะ? ดูไม่ค่อยดีเลย"
L3_1.m_Talk_VTN = "Cô có sao không, Nao? Trông cô không tốt lắm."
L3_1.m_Talk_SCN = "奈绪大人，您没事吧？从刚才开始，您的脸色就不太好。"
L3_1.m_Talk_DEU = "Geht es Ihnen gut, Fräulein Nao? Sie sehen blass aus."
L3_1.m_Talk_FRA = "Ça va, madame Nao ? Vous avez l'air épuisée."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "NANAHARA2_ACT1_INTERLUDE3@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 5100108
L4_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L4_1.m_bWaitClick = true
