L4_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L4_1.m_Pos = "R"
L4_1.m_Talk_KOREA = "사람이라면…… 자고로 땅을 밟고 살아야 하는 것을-"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "人間たるもの……土を踏んで生きるべし……"
L4_1.m_Talk_ENG = "Humans belong on land, not in air..."
L4_1.m_Talk_TWN = "自古以來……人就是要在這塊土地上掘地而居-"
L4_1.m_Talk_THA = "มนุษย์ควรอยู่บนพื้นนะ ไม่ใช่ในอากาศบางๆ แบบนี้..."
L4_1.m_Talk_VTN = "Con người thuộc về đất liền, không phải tuốt trên cao với không khí loãng thế này..."
L4_1.m_Talk_SCN = "自古以来……人就是要脚踏实地生活——"
L4_1.m_Talk_DEU = "Menschen gehören auf den Boden, nicht in die Luft ..."
L4_1.m_Talk_FRA = "Les humains appartiennent à la terre, pas au ciel..."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "NANAHARA2_ACT1_INTERLUDE3@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 5100108
L5_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L5_1.m_Pos = "R"
L5_1.m_Talk_KOREA = "이런 마천루에 터를 잡고 지내다니…… 가문연합의 위세도 갈 때까지 갔구나."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "こんな摩天楼に住みつくとは……連合の威勢も廃れたもんじゃのう。"
L5_1.m_Talk_ENG = "To set this pagoda of a place as your dwelling... it looks like the Alliance has become more than arrogant."
L5_1.m_Talk_TWN = "竟然在這種摩天大樓定居……難怪家族聯盟會沒落。"
L5_1.m_Talk_THA = "มาสร้างเจดีย์พรรค์นี้ในที่ที่พวกเจ้าอยู่กันนี่... ท่าทางเดี๋ยวนี้ทางสมาพันธ์จะยิ่งกว่าจองหองเสียแล้วสิ"
L5_1.m_Talk_VTN = "Biến ngôi chùa này thành chỗ ở...có vẻ như Liên Minh đã trở nên rất kiêu ngạo."
L5_1.m_Talk_SCN = "你们居然在这种摩天大楼上安家……看来家族联盟的威势，走到尽头也不无道理。"
L5_1.m_Talk_DEU = "Wenn ihr auf so einem Wolkenkratzer lebt ... scheint das Ansehen der Familienallianz ja gestiegen zu sein."
L5_1.m_Talk_FRA = "Que fait cette pagode à une altitude pareille ? On dirait que le Clan a pris un sacré melon."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "NANAHARA2_ACT1_INTERLUDE3@6#Talk"
L6_1.m_CutScenProcessKey = 6
