L6_1.m_Pos = "L"
L6_1.m_Talk_KOREA = "네? 저희 가문연합에 대해 알고 계셨나요?"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "はい？　連合についてご存じでしたか？"
L6_1.m_Talk_ENG = "Huh? Have you heard of us before?"
L6_1.m_Talk_TWN = "什麼？你認識我們家族聯盟嗎？"
L6_1.m_Talk_THA = "หือ? ท่านเคยได้ยินเรื่องพวกเรามาก่อนด้วยหรือคะ?"
L6_1.m_Talk_VTN = "Huh? Cô đã từng nghe về chúng tôi rồi sao?"
L6_1.m_Talk_SCN = "呃？您知道我们家族联盟吗？"
L6_1.m_Talk_DEU = "Wie bitte? Kennen Sie etwa unsere Familienallianz?"
L6_1.m_Talk_FRA = "Pardon ? Vous connaissez notre clan ?"
L7_1 = {}
