L7_1.m_Talk_VTN = "Hmph... Tất nhiên là có rồi. Tôi đã nhận quá nhiều người học việc từ chỗ các cô."
L7_1.m_Talk_SCN = "哼……当然知道。我还在里面收过徒弟呢。"
L7_1.m_Talk_DEU = "Hmpf ... Natürlich. Ich habe von euch bereits etliche Lehrlinge eingestellt."
