L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "당주님께서 독에 당한 손님이 있다고 하셔서 왔습니다만……"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "ご当主様から毒にやられたお客様がいると聞き、やってまいりましたが……"
L20_1.m_Talk_ENG = "I heard that there was a guest who has been poisoned..."
L20_1.m_Talk_TWN = "堂主說有位中毒的客人，需要我來……"
L20_1.m_Talk_THA = "ข้าน้อยได้ยินว่ามีแขกที่โดนวางยาพิษ..."
L20_1.m_Talk_VTN = "Tôi nghe nói có một vị khách bị trúng độc..."
L20_1.m_Talk_SCN = "家主说有个中毒的客人，需要我来……"
L20_1.m_Talk_DEU = "Ich habe gehört, dass es einen Gast gibt, der vergiftet wurde ..."
L20_1.m_Talk_FRA = "J'ai accouru aussi vite que j'ai pu quand on m'a dit que votre invitée souffrait d'une blessure empoisonnée, mais..."
