L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "ウマいのう～おかわり～"
L22_1.m_Talk_ENG = "Ah, scrumptious! Another bowl!"
L22_1.m_Talk_TWN = "真好吃～再來一碗～"
L22_1.m_Talk_THA = "อาห์ อร่อยชะมัด! ขออีกชามนะ!"
L22_1.m_Talk_VTN = "Ah, hảo hạng! Làm ơn cho bát nữa nhé!"
