L24_1 = {}
L24_1.m_CutScenKey_Talk = "NANAHARA2_ACT1_INTERLUDE3@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 5100108
L24_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "SERVANT_NPC_NANAHARA_NULL"
L24_1.m_Talk_KOREA = "네. 필요한 반찬이 더 있으시면 말씀만 하세요, 나오님."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "はい。必要なおかずがございましたらなんなりとお申しつけください、ナオ様。"
L24_1.m_Talk_ENG = "Yes, Miss Nao. Do let us know if there is anything else you need."
L24_1.m_Talk_TWN = "好的，若是有需要加小菜也儘管說。"
L24_1.m_Talk_THA = "ได้ค่ะ คุณนาโอะ ต้องการอะไรก็แจ้งให้เราทราบนะคะ"
L24_1.m_Talk_VTN = "Được thôi, cô Nao! Cứ nói nếu cô cần bất cứ thứ gì nhé."
L24_1.m_Talk_SCN = "好，还需要别的小菜的话请告诉我，奈绪大人。"
L24_1.m_Talk_DEU = "Sehr wohl, Fräulein Nao. Lassen Sie uns wissen, wenn Sie noch etwas benötigen."
L24_1.m_Talk_FRA = "Entendu. Faites-nous savoir si vous avez besoin de quoi que ce soit d'autre."
