L26_1 = {}
L27_1 = "NANAHARA2_ACT1_INTERLUDE3@26#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 26
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5100108
L26_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_DESPAIR"
L26_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "죄송해요, 사나에. 식사를 하시더니 금방 생기를 되찾으셨어요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ごめんなさい、早苗。食事をされてからすぐに元気になられて。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I am sorry, Sanae. She got better as soon as she started eating."
L26_1.m_Talk_ENG = L27_1
L27_1 = "早苗，抱歉，她吃過飯後就恢復精神了。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ข้าขอโทษด้วยนะซานาเอะ แต่พอได้ทานแล้วนางก็เริ่มดีขึ้นทันที"
L26_1.m_Talk_THA = L27_1
L27_1 = "Xin lỗi nhé, Sanae. Cô ấy đã khỏe hơn ngay sau khi ăn."
L26_1.m_Talk_VTN = L27_1
L27_1 = "对不起，早苗。吃完饭马上就恢复活力了呢。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Tut mir leid, Sanae. Sie hat sich erholt, sobald sie anfing zu essen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Je suis désolée, Sanae. Son état s'est amélioré dès qu'elle a commencé à manger."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "NANAHARA2_ACT1_INTERLUDE3@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5100108
L27_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_LAUGH"
L27_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "당연한 것 아니겠냐! 예로부터 밥심으로 낫지 않는 병은 없었다!"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "当たり前じゃ！　昔からご飯の力で治らない病などない！"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Of course I did! A good meal is a cure to everything!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "那不是當然的嗎！自古以來沒有什麼病是一頓飯醫不好的！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ใช่แล้ว! ของอร่อยจะเยียวยาทุกสิ่ง!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tất nhiên rồi! Một bữa ngon là liều thuốc chữa lành mọi thứ!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "那不是理所当然的吗！自古以来就没有吃饭治不好的病！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Natürlich habe ich das getan! Eine gute Mahlzeit heilt schließlich alles!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "C'est normal, non ? Un bon repas, c'est le meilleur des remèdes !"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
