L31_1 = "하야미 가문의 하야미 사나에. 나오님을 이렇게 뵙습니다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "速水家の速水早苗。ナオ様にご挨拶申し上げます。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Hayami Sanae of the Hayami family greets you, Miss Nao."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我是速水家族的速水早苗，見過奈緒大人。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฮายามิ ซานาเอะแห่งตระกูลฮายามิขอแสดงการทักทายค่ะ ท่านนาโอะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Hayami Sanae của gia tộc Hayami có lời chào cô, Cô Nao."
L30_1.m_Talk_VTN = L31_1
L31_1 = "速水家族的速水早苗，拜见奈绪大人。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich bin Hayami Sanae von der Familie Hayami. Freut mich Sie kennenzulernen, Fräulein Nao."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Hayami Sanae de la famille Hayami vous salue, madame Nao."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
