L34_1.m_Pos = "L"
L35_1 = "오, 눈을 보아하니 네가 하야미 집안의 후손이로구나."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "おお、目を見れば、お主が速水家の末裔か。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Judging from your eyes, you must be a Hayami indeed."
L34_1.m_Talk_ENG = L35_1
L35_1 = "喔，看你的眼神確實是速水家族的後裔沒錯。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ดูจากดวงตาแล้ว เจ้าเป็นคนบ้านฮายามิจริงๆ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Xem đôi mắt của cô thì cô quả thực là một người nhà Hayami."
L34_1.m_Talk_VTN = L35_1
L35_1 = "噢，看你的眼睛，果然是速水家族的后代。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Deinen Augen nach zu urteilen, scheinst du tatsächlich eine Hayami sein."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Oh, c'est vrai que tu as les yeux d'une Hayami."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NANAHARA2_ACT1_INTERLUDE3@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5100108
L35_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L35_1.m_Pos = "L"
L36_1 = "나나하라류는 잘 계승하고 있겠지?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "七原流はちゃんと受け継いでいるな？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I assume you are still practicing the Nanahara Style?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "你有好好繼承七原流吧？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ท่าทางจะยังฝึกวิชาต่อสู้สายนานะฮาระอยู่สินะ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi cho là cô vẫn đang tập Trường Phái Nanahara nhỉ?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "你有好好继承七原流吧？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich nehme an, dass du immer noch den Nanahara-Stil praktizierst?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tu pratiques toujours le style de l'école Nanahara, je suppose ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA2_ACT1_INTERLUDE3@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5100108
L36_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_DESPAIR"
L36_1.m_CharStrID = "SANAE_NANA_NULL_NULL"
L36_1.m_Pos = "R"
L37_1 = "예. 비록 정식 사범은 아니지만, 나나하라류의 명맥을 지키는 것이 사명이니까요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "はい。正式の師範ではございませんが、七原流の命脈を保つことが私の使命でございますゆえ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Yes. I am not an official instructor, but it is it my duty to pass down its heritage."
L36_1.m_Talk_ENG = L37_1
L37_1 = "是的，雖然我還不是正式師範，守護七原流的命脈是我的使命。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ค่ะ ข้าน้อยไม่ใช่ผู้สอนวิชาอย่างเป็นทางการ แต่ก็เป็นหน้าที่ที่ต้องส่งต่อให้สืบทอดไปค่ะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đúng. Tôi không phải là người hướng dẫn chính thức nhưng tôi có nhiệm vụ truyền bá di sản của nó."
L36_1.m_Talk_VTN = L37_1
L37_1 = "是的，虽然不是正式教习，但守护七原流的命脉是我的使命。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ja. Ich bin zwar keine offizielle Ausbilderin, aber es ist dennoch meine Pflicht, das Erbe des Nanahara-Stils weiterzugeben."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Oui. Je ne suis pas une instructrice officielle, mais c'est mon devoir de transmettre son héritage."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
