L42_1 = "Excuse me, but... do you know each other?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "請問……你們是舊識嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ขอโทษนะคะ แต่ว่า... ทั้งสองคนรู้จักกันเหรอคะ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Xin lỗi, nhưng... hai người có biết nhau không?"
