L44_1 = "저도 관리국 데이터베이스를 통해 알고 있을 뿐, 직접 뵙는 것은 처음입니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "私も管理局のデータベースを見て存じ上げているだけで、直接お会いするのは初めてです。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I only know of Miss Nao from the Administration database. It is my first time seeing her."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我也是透過管理局的資料庫才知道奈緒大人的，見到本人這是第一次。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ข้าน้อยแค่รู้จักท่านนาโอะจากฐานข้อมูลองค์การบริหารโลกค่ะ แต่เพิ่งเคยเจอกันครั้งแรก"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi chỉ biết về cô Nao từ cơ sở dữ liệu của Cục Quản Lý. Đây là lần đầu tôi gặp cô ấy."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我也是通过管理局的数据库才知道的，见到本人还是第一次。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich kenne Fräulein Nao nur aus der Datenbank der Administration. Es ist das erste Mal, dass ich sie persönlich treffe."
L43_1.m_Talk_DEU = L44_1
L44_1 = "J'ai entendu parler de madame Nao via la base de données de l'Administration, mais c'est la première fois que je la rencontre."
L43_1.m_Talk_FRA = L44_1
