L50_1 = "我真是有眼不識泰山。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ขออภัยที่ไม่ได้สังเกตนะคะ ท่านนาโอะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi xin lỗi vì đã vô ý, Cô Nao."
