L2_1 = "NANAHARA2_ACT1_INTERLUDE3@51#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 5100108
L1_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_LAUGH"
L1_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L1_1.m_Pos = "L"
L2_1 = "괜찮다. 모를 만도 하지. 내가 자릴 비운 건 네놈들 증조가 태어나기도 전이니 말이야."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "気にするな。わからなくて当然じゃ。わしが戦隊を離れたのはお主たちの曾祖父が生まれる前だからのう。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "It’s fine. Of course you didn’t know. I left my place before your ancestors were even born."
L1_1.m_Talk_ENG = L2_1
L2_1 = "沒事，不知道是正常的，畢竟我退休的時候，你們的曾祖輩應該都還沒出生吧。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "จะเป็นไรไป เจ้าย่อมต้องไม่รู้อยู่แล้ว ข้าไปจากที่นี่ก่อนบรรพบุรุษเจ้าจะถือกำเนิดเสียอีก"
L1_1.m_Talk_THA = L2_1
L2_1 = "Không sao. Dĩ nhiên là cô không biết rồi. Tôi đã rời khỏi nơi này từ trước khi tổ tiên của cô sinh ra."
L1_1.m_Talk_VTN = L2_1
L2_1 = "没关系。没认出来也正常。我退隐的时候，你们的曾祖还没出生呢。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Schon gut. Natürlich konntest du das nicht. Ich habe meine Heimat verlassen, bevor deine Vorfahren überhaupt geboren wurden."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Ça va, tu ne pouvais pas savoir. Puisque j'ai quitté mon poste quand vos ancêtres n'étaient pas encore nés !"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NANAHARA2_ACT1_INTERLUDE3@52#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5100108
L2_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_SURPRISE"
L2_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L2_1.m_Pos = "R"
L3_1 = "그렇게나 오래 전부터……"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "そんなにも昔から……"
L2_1.m_Talk_JPN = L3_1
L3_1 = "For all this time..."
L2_1.m_Talk_ENG = L3_1
L3_1 = "那麼久以前的事嗎……"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เนิ่นนานถึงเพียงนั้น..."
L2_1.m_Talk_THA = L3_1
L3_1 = "Trong suốt thời gian này..."
L2_1.m_Talk_VTN = L3_1
L3_1 = "是那么久之前的事吗……"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Vor so langer Zeit ..."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ça fait si longtemps... ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "NANAHARA2_ACT1_INTERLUDE3@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5100108
L3_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "UNIT_IDLE"
L3_1.m_Face = L4_1
L3_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L3_1.m_Pos = "R"
L4_1 = "그런데도 무척 젊어 보이시네요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "それなのにとてもお若く見えますね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "But you still look so young, Miss Nao."
L3_1.m_Talk_ENG = L4_1
L4_1 = "但您看起來很年輕呢。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แต่ท่านยังดูเยาว์วัยนัก ท่านนาโอะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nhưng trông cô còn rất trẻ mà, Cô Nao."
L3_1.m_Talk_VTN = L4_1
L4_1 = "不过您看来非常年轻。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Aber Sie sehen immer noch so jung aus."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Mais vous semblez si jeune, pourtant !"
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "NANAHARA2_ACT1_INTERLUDE3@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 5100108
L4_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L4_1.m_Pos = "L"
L5_1 = "그러냐? 나도 너처럼 작은 당주는 처음 본다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そうか？　わしもお主のようなチビ当主は初めて見るわい。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Is that so? It’s my first time seeing a Ladychild like you, too."
L4_1.m_Talk_ENG = L5_1
L5_1 = "是嗎？我也是第一次看到像你這麼小的堂主呢。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เช่นนั้นรึ? ข้าเองก็เพิ่งเคยเจอท่านหญิงน้อยเช่นเจ้าเหมือนกันนะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Vậy sao? Đây cũng là lần đầu tiên tôi thấy một Tiểu Thư bé nhỏ như cô."
L4_1.m_Talk_VTN = L5_1
L5_1 = "是吗？我也是第一次见到你这样的小家主。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Ach echt? Es ist auch das erste Mal, dass ich eine so zierliche Anführerin wie dich sehe."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Ah oui ? Remarque, c'est la première fois que je vois une mioche comme toi à la tête du clan."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
