L9_1 = "NANAHARA2_ACT1_INTERLUDE3@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 5100108
L8_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "SANAE_NANA_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "나오님께선 선조신의 직계 후손이십니다. 저희와 달리 사람 피가 거의 섞이지 않으셨지요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ナオ様は冥府の神々の直系子孫でいらっしゃいます。私たちとは違い、人間の血はほとんど混ざっていません。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Miss Nao is the direct descendant of the ancestral gods. Unlike us, there is very little human blood that flows in her."
L8_1.m_Talk_ENG = L9_1
L9_1 = "奈緒大人是祖先神的直系後裔，她和我們不同，她的血液裡幾乎沒有任何的參雜。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ท่านนาโอะเป็นผู้สืบสายเลือดเหล่าเทพเจ้าโดยตรง ซึ่งต่างจากพวกเรานะคะ ในกายนางจะมีเลือดมนุษย์เพียงน้อยนิด"
L8_1.m_Talk_THA = L9_1
L9_1 = "Cô Nao là hậu duệ trực hệ của thần thánh. Không giống chúng ta, có rất ít máu huyết con người chảy bên trong huyết quản cô ấy."
L8_1.m_Talk_VTN = L9_1
L9_1 = "奈绪大人是先祖神的直系后代。和我们不同，她的血脉中几乎没有掺杂人类的成分。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Fräulein Nao ist ein direkter Nachkomme unserer Ahnengötter. Im Gegensatz zu uns fließt durch ihre Adern nur sehr wenig menschliches Blut."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Madame Nao est la descendante direct des dieux ancestraux. Contrairement à nous, il n'y a que très peu de sang humain qui coule dans ses veines."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "NANAHARA2_ACT1_INTERLUDE3@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5100108
L9_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "네? 그렇다면 과거엔 나오님 같은 신이 고르디우스 전대에 계셨던 건가요?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "それでは過去にはナオ様のような神がゴルディウス戦隊にいらっしゃったのですか？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Huh? Does that mean that there were gods like you in the Gordias Division?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "什麼？你的意思是戈爾迪亞戰隊中曾經有像奈緒大人這樣的神嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "หา? หมายความว่าในกองพลกอร์เดียสมีเทพเจ้าแบบท่านอยู่ด้วยเหรอคะ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Hả? Điều đó có nghĩa là ở Sư đoàn Gordias có những vị thần như cô sao?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "什么？那你的意思是过去戈尔迪亚战队还有奈绪大人这样的神吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Häh? Bedeutet das, dass es in der Gordias-Division Götter wie Sie gab?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Comment ? Alors dans le passé, la Division Gordias était constituée de dieux ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NANAHARA2_ACT1_INTERLUDE3@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 60
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 5100108
L10_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "착각하고 있구나. 내가 신이었다면 진작에 죽거나 저승에 묻혔겠지."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "勘違いがあるな。わしが神だったらすでに死んでいるか、冥府に送られておるわ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "You’re getting the wrong idea. If I was a god, I would have been long past dead, or buried in the Afterlife."
L10_1.m_Talk_ENG = L11_1
L11_1 = "並非如此，我要是神的話，早就已經死掉或是被埋在地獄裡。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เข้าใจผิดกันหมดแล้ว ถ้าข้าเป็นเทพเจ้าคงไม่ตายไปตั้งนานแล้วหรือถูกฝังไว้ในโลกหลังความตายหรอก"
L10_1.m_Talk_THA = L11_1
L11_1 = "Cô hiểu nhầm rồi. Nếu tôi là thần, tôi đã chết từ lâu, hoặc bị chôn vùi ở Thế Giới Bên Kia."
L10_1.m_Talk_VTN = L11_1
L11_1 = "你们误会了。如果我是神，早就已经死掉或者被埋在地府了。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Es scheint ein Missverständnis zu geben. Wenn ich ein Gott wäre, wäre ich längst tot oder im Jenseits begraben."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Nous, tu fais fausse route. Si j'étais vraiment une déesse, je serais morte depuis longtemps. Ou enterrée dans l'Au-delà, au choix."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NANAHARA2_ACT1_INTERLUDE3@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 5100108
L11_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "UNIT_IDLE"
L11_1.m_Face = L12_1
L11_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "관리국에선 나를 반쪽짜리 환상종이라고 부르긴 했다만……"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "管理局ではわしを不完全な幻想種と呼んではいたんじゃが……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "The Administration used to call me as a half-Bygone...."
L11_1.m_Talk_ENG = L12_1
L12_1 = "不過管理局都稱我是半夢幻類……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "องค์การบริหารโลกเคยเรียกข้าว่าพวกกึ่งบายกอน..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Cục Quản Lý còn từng gọi tôi là một nửa Bygone nữa cơ..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "按照管理局的说法，我算是半个幻想种……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Die Administration nannte mich eine „Vergangene“ ..."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Les types de l'Administration m'appellent « Demi-Chimère »..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "NANAHARA2_ACT1_INTERLUDE3@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5100108
L12_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_LAUGH"
L12_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L12_1.m_Pos = "C"
L13_1 = "뭐, 좋을 대로 부르거라."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "まあ、好きに呼べ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Whatever. Call me whatever you please."
L12_1.m_Talk_ENG = L13_1
L13_1 = "叫什麼都好啦。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "แต่เอาเถิด จะเรียกข้าเช่นไรก็แล้วแต่ใจเจ้า"
L12_1.m_Talk_THA = L13_1
L13_1 = "Sao cũng được. Cứ gọi tôi thế nào cũng ok."
L12_1.m_Talk_VTN = L13_1
L13_1 = "嗯，随便你们怎么称呼吧。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Wie auch immer. Nenn mich, wie du willst."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Enfin, ça n'a pas d'importance. Appelle-moi comme tu veux."
L12_1.m_Talk_FRA = L13_1
