L16_1 = "NANAHARA2_ACT1_INTERLUDE3@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5100108
L15_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_SERIOUS"
L15_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "그렇다면 나오님께 한 가지 여쭙고 싶은 것이 있습니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "では、ナオ様に一つお伺いしたいことがあります。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I would like to ask you one question, Miss Nao."
L15_1.m_Talk_ENG = L16_1
L16_1 = "那，我可以問奈緒大人一個問題嗎？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ข้ามีคำถามอยากถามสักหนึ่งข้อค่ะ ท่านนาโอะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi muốn hỏi cô một câu, cô Nao."
L15_1.m_Talk_VTN = L16_1
L16_1 = "那么，我可以问奈绪大人一个问题吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich möchte Ihnen eine Frage stellen, Fräulein Nao."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Puis-je vous poser une question, madame Nao ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NANAHARA2_ACT1_INTERLUDE3@66#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 66
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 5100108
L16_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "뭐냐?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "何じゃ？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "And what’s that?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "什麼問題？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "และคำถามที่ว่าก็คือ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Hỏi gì nào?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "你说？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Was denn?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Quoi donc ?"
L16_1.m_Talk_FRA = L17_1
