L18_1 = "NANAHARA2_ACT1_INTERLUDE3@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5100108
L17_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_SERIOUS"
L17_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "오늘 저희가 만난 것은…… 우연인가요? 아니면 필연인가요?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "今日私たちが出会ったのは……偶然ですか？　それとも必然ですか？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Our encounter today... Was it coincidence? Or fate?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "我們今日的相遇……是偶然？還是必然呢？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ที่เราพบกันวันนี้... เป็นเรื่องบังเอิญใช่มั้ยคะ? หรือคือโชคชะตา?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cuộc gặp gỡ của chúng ta hôm nay... Là trùng hợp? Hay là định mệnh?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "今天我们的相遇……是偶然？还是必然呢？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Unsere Begegnung heute ... war es nur ein Zufall? Oder war es Schicksal?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Notre rencontre aujourd'hui... était-ce une coïncidence ? Ou un signe du destin ?"
L17_1.m_Talk_FRA = L18_1
