L22_1 = "NANAHARA2_ACT1_INTERLUDE3@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5100108
L21_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "그럼 배도 채웠겠다. 슬슬 용건을 읊어볼까?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "さあ、腹ごしらえもしたし。そろそろ用件を話してみるかのう。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Well, then. Now that I’m full, Let’s get down to business."
L21_1.m_Talk_ENG = L22_1
L22_1 = "我看大家應該都吃飽了，那就來談談正事吧？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เอาล่ะ ข้าอิ่มแล้ว มาคุยธุระกันดีกว่า"
L21_1.m_Talk_THA = L22_1
L22_1 = "Chà. Giờ tôi no rồi. Hãy làm việc chính nào."
L21_1.m_Talk_VTN = L22_1
L22_1 = "好了，现在也吃饱喝足了，该说正事了吧？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Na dann. Jetzt, wo ich satt bin, kommen wir mal zur Sache."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Pfiouh ! J'ai bien mangé. Et maintenant, passons aux choses sérieuses."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NANAHARA2_ACT1_INTERLUDE3@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5100108
L22_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "너희. <color=#ffd34c>역신베기</color>라고 들어봤느냐?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "お主たち。<color=#ffd34c>大蛇薙剣</color>という名を聞いたことはあるか？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Have any of you heard of <color=#ffd34c>Orochinagi</color>?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "你們聽過<color=#ffd34c>瘟神斬</color>嗎？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เคยได้ยินชื่อ<color=#ffd34c>โอโรจินางิ</color>หรือไม่?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Có ai trong số các cô nghe nói về <color=#ffd34c>Orochinagi</color> không ?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "你们，听说过<color=#ffd34c>瘟神斩</color>吗？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Habt ihr schon mal vom <color=#ffd34c>Orochinagi</color> gehört?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Vous autres, avez-vous déjà entendu parler de l'<color=#ffd34c>Orochinagi</color> ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NANAHARA2_ACT1_INTERLUDE3@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 5100108
L23_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "……역신을 막아낼 삼신기 중 유일하게 완성되지 않은 하나라고 배웠습니다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "……疫病神の復活を阻止する三神器のうち、唯一完成していない神器であると教わりました。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "...I heard that it is the only Sacred Treasure that has not been finished out of the Three."
L23_1.m_Talk_ENG = L24_1
L24_1 = "……我聽說那是可以阻止瘟神的三神器中，唯一一個沒有完成的神器。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "...ได้ยินว่าเป็นสมบัติศักดิ์สิทธิ์เพียงหนึ่งเดียวในสามชิ้นที่ยังสร้างไม่เสร็จนี่คะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "...Tôi nghe nói đó là Thần Khí duy nhất chưa hoàn thiện trong số ba Thần Khí."
L23_1.m_Talk_VTN = L24_1
L24_1 = "……我听说那是可以阻止瘟疫之神的三神器中唯一一个未完成的神器。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "... Ich habe gehört, dass es der einzige der drei Heiligen Schätze ist, der noch nicht vollendet wurde."
L23_1.m_Talk_DEU = L24_1
L24_1 = "... Il s'agit d'une des trois lames sacrées. La seule des trois qui n'a jamais été achevée."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "NANAHARA2_ACT1_INTERLUDE3@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 5100108
L24_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L24_1.m_Pos = "C"
L25_1 = "그래."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "そうじゃ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Right."
L24_1.m_Talk_ENG = L25_1
L25_1 = "沒錯。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ใช่"
L24_1.m_Talk_THA = L25_1
L25_1 = "Đúng vậy."
L24_1.m_Talk_VTN = L25_1
L25_1 = "没错。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Genau."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Correct."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "NANAHARA2_ACT1_INTERLUDE3@75#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 75
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5100108
L25_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "나는 선조들의 유지를 받들어, 그 역신베기를 완성하러 온 거다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "わしは先祖たちの遺志を受け、大蛇薙剣を完成させるために来たのじゃ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I came here to complete Orochinagi, upon the legacy of our ancestors."
L25_1.m_Talk_ENG = L26_1
L26_1 = "而我承接祖先的遺願，是要來完成瘟神斬的。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ข้ามาเพื่อสร้างโอโรจินางิให้สำเร็จ ในฐานะมรดกตกทอดของบรรพบุรุษเรา"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi đến đây để hoàn thành Orochinagi, dựa trên di sản của tổ tiên chúng ta."
L25_1.m_Talk_VTN = L26_1
L26_1 = "我是继承先祖们的遗志，来完成瘟神斩的。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich bin hierher gekommen, um das Orochinagi auf der Grundlage des Erbes unserer Vorfahren zu vollenden."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Eh bien, je suis venue ici pour terminer le travail. Et perpétuer la volonté des ancêtres, accessoirement."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "NANAHARA2_ACT1_INTERLUDE3@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5100108
L26_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "그러니 하야미 가문의 무사들을 전부 한 자리에 불러 모으거라."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ゆえに速水家の武士を全員ここに呼び集めろ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Which is exactly why I need you to gather up the Hayami warriors."
L26_1.m_Talk_ENG = L27_1
L27_1 = "所以我要你們立刻召集所有速水家族的武士。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "และด้วยเหตุนั้น ข้าจึงต้องรวบรวมทหารของบ้านฮายามิ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Đó chính xác là lý do tại sao tôi cần cô tập hợp những người lính nhà Hayami."
L26_1.m_Talk_VTN = L27_1
L27_1 = "所以，把速水家族的所有武士都召集到一起吧。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Deshalb musst du alle Krieger der Hayami Familie hierher rufen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Alors j'aurais besoin que vous rassembliez tous les guerriers de la famille Hayami ici."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
