L28_1.m_CharStrID = "SANAE_NANA_NULL_NULL"
L28_1.m_Pos = "C"
L29_1 = "하야미 가문 무사는 소인 하나뿐이니까요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "速水家の武士は私一人だけですから。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I am the sole Hayami warrior that is left."
L28_1.m_Talk_ENG = L29_1
L29_1 = "因為速水家族的武士只剩我一人。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ข้าน้อยคือทหารฮายามิเพียงผู้เดียวที่เหลืออยู่แล้ว"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tôi là người lính Hayami duy nhất còn lại."
L28_1.m_Talk_VTN = L29_1
L29_1 = "速水家族的武士现在就只剩下我一个了。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ich bin die einzige Kriegerin der Hayami Familie, die noch übrig ist."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Je suis la seule représentante de la famille Hayami encore en vie."
L28_1.m_Talk_FRA = L29_1
