L31_1 = "NANAHARA2_ACT1_INTERLUDE3@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5100108
L30_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "아무리 시대가 변했다 한들 하야미 가문에 검을 다루는 인재가 그렇게 없다는 거냐?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "いくら時代が変わったとて、速水家に剣術に長けた者がそれほどまでにいないのか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I know that times have changed, but surely there should be more talents in the Hayami family?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "就算時代再怎麼變，速水家族中可以拿劍的人才也不至於這麼少吧？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อันเวลาผันผ่านไปแล้วข้าย่อมรู้ แต่ก็ตระกูลฮายามิก็น่าจะมีผู้มีฝีมืออยู่มากกว่านี้มิใช่รึ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi biết rằng thời thế đã thay đổi, nhưng chắc chắn phải còn nhiều nhân tài khác trong gia tộc Hayami chứ?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "就算时代再怎么变，速水家族用剑的人才，已经凋零到这种程度了吗？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich weiß, dass sich die Zeiten geändert haben, aber es sollte doch sicher mehr Mitglieder der Hayami Familie geben, die mit einem Schwert umgehen können."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je sais bien que les temps ont changé, mais quand même... n'y avait-il pas plus de guerriers talentueux dans ta lignée ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NANAHARA2_ACT1_INTERLUDE3@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5100108
L31_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_DESPAIR"
L31_1.m_CharStrID = "SANAE_NANA_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "20년 전, 저희 하야미 가문은 모두 전투에 참전했습니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "20年前、私たち速水家は全員戦闘に参戦いたしました。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "20 years ago, the Hayami family was dispatched to a certain battle."
L31_1.m_Talk_ENG = L32_1
L32_1 = "20年前，我們速水家族全員投身戰場。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "20 ปีก่อน ตระกูลฮายามิได้รับมอบหมายให้ไปทำศึกหนึ่งค่ะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "20 năm trước, gia tộc Hayami đã được phái tới một trận chiến nào đó."
L31_1.m_Talk_VTN = L32_1
L32_1 = "20年前，我们速水家族全员投身于战斗。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Vor 20 Jahren wurde die gesamte Hayami Familie in eine Schlacht entsandt."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Il y a 20 ans, la famille Hayami a pris part à une certaine... bataille."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "NANAHARA2_ACT1_INTERLUDE3@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5100108
L32_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "SANAE_NANA_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "소인도 그날 죽음을 각오하였으나, 깨어났을 땐 저 혼자만 살아남았지요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私もあの日死を覚悟していたのですが、目覚めた時には一人だけ生き残っていました。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I too was prepared for death, however... when I woke up, I realized I was the sole survivor."
L32_1.m_Talk_ENG = L33_1
L33_1 = "那天我也是抱著必死的決心上戰場，但當我醒過來後，卻發現只剩我一人獨活。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ข้าน้อยเองก็เตรียมใจไปตาย ทว่า... เมื่อฟื้นขึ้นมา กลับพบว่าตัวเองเป็นผู้รอดชีวิตเพียงคนเดียว"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi cũng đã chuẩn bị cho cái chết, tuy nhiên... khi tỉnh dậy, tôi nhận ra mình là người sống sót duy nhất."
L32_1.m_Talk_VTN = L33_1
L33_1 = "那天我也做好了赴死的准备，但醒来时就只有我一个人活了下来。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Auch ich war auf den Tod vorbereitet, aber als ich aufwachte, wurde mir klar, dass ich die einzige Überlebende war."
L32_1.m_Talk_DEU = L33_1
L33_1 = "J'étais prête à mourir au combat, moi aussi. Mais quand je me suis réveillée... il ne restait plus que moi."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
