L34_1 = "20年前嗎……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "20 ปีที่แล้วที่เจ้าว่าก็คือ..."
L33_1.m_Talk_THA = L34_1
L34_1 = "Ý của cô là 20 năm trước là..."
