L34_1 = "20年前的话……"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Wenn es vor 20 Jahren war, dann ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Il y a 20 ans ? Alors ça doit être..."
