L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5100108
L34_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_HATE"
L34_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "……쳇, 됐다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "……ちっ、もうよい。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "...Tch. Forget it."
L34_1.m_Talk_ENG = L35_1
L35_1 = "……嘖，就這樣吧。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "...ชิ ช่างเหอะ"
