L36_1 = "NANAHARA2_ACT1_INTERLUDE3@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5100108
L35_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "그럼 검도 휘두르지 못하는 네가 나나하라류를 계승한 유일한 무사라는 거냐?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "それじゃあ、刀も振るえないお主が七原流を継承した唯一の武士なのか？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "So you’re saying that you, who can’t even dare to wield your own blade, are the only successor of the Nanahara Style?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "所以現在不懂拿劍的你是唯一繼承七原流的武士嗎？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "สรุปคือกำลังบอกว่าเจ้าผู้ไม่กล้าแม้แต่จะเหวี่ยงดาบของตัวเอง\nเป็นผู้สืบทอดวิชาต่อสู้สายนานะฮาระเพียงคนเดียวเช่นนั้นรึ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Vậy cô đang nói rằng cô, người thậm chí không thể vung kiếm lên, là người kế thừa duy nhất của Trường Phái Nanahara sao?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "那也就是说，连挥剑都不利索的你，是继承七原流的唯一武士？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Du meinst also, dass du, die nicht einmal in der Lage ist, ihre eigene Klinge zu führen, die einzige Nachfolgerin des Nanahara-Stils bist?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Dois-je donc comprendre que tu es la seule ici à maîtriser les arcanes du style Nanahara ? Toi qui n'oses même pas lever ton arme ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
