L37_1 = "UNIT_IDLE"
L36_1.m_Face = L37_1
L36_1.m_CharStrID = "SANAE_NANA_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "비록 하야미 가문의 사람은 아니지만……"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "速水の者ではありませんが……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Despite not being a Hayami..."
L36_1.m_Talk_ENG = L37_1
L37_1 = "還有一個人，雖然她不是速水家族的人……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แม้จะไม่ใช่ฮายามิ..."
L36_1.m_Talk_THA = L37_1
L37_1 = "Mặc dù không phải là một người nhà Hayami..."
L36_1.m_Talk_VTN = L37_1
L37_1 = "还有一个人，虽然不是出身于速水家族……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Obwohl es nicht zur Hayami Familie gehört ..."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Non. Il y a quelqu'un d'autre que moi."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
