L38_1 = "저보다 자질이 뛰어난 아이가 하나 있습니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "私より優れた実力を持っている子が一人おります。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "There is one child who excels at it."
L37_1.m_Talk_ENG = L38_1
L38_1 = "但她比我有天賦。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่ก็มีเด็กคนหนึ่งเป็นเลิศในเรื่องนั้นค่ะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nhưng có một đứa trẻ rất giỏi."
L37_1.m_Talk_VTN = L38_1
L38_1 = "但她比我有天赋。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Gibt es ein Kind, das noch begabter als ich ist."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ce n'est pas une Hayami, mais... son talent est certain."
