L43_1 = "CHIFUYU_NANA_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "그 자의 공격은 나보다 빠르거나 강하지 않았다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "あの者の攻撃は私より早くも、強くもなかった。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Her attacks were not faster nor stronger than mine."
L42_1.m_Talk_ENG = L43_1
L43_1 = "她的攻擊並沒有比我快，也沒有比我強。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "การโจมตีของนางไม่ได้รวดเร็วหรือแข็งแกร่งกว่าข้า"
L42_1.m_Talk_THA = L43_1
L43_1 = "Các đòn tấn công của cô ta không nhanh hơn và cũng không mạnh hơn của mình."
L42_1.m_Talk_VTN = L43_1
L43_1 = "她的攻击并没有比我快，或者比我强。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ihre Angriffe waren weder schneller noch stärker als meine."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ses attaques ne sont ni plus rapides, ni plus puissantes que les miennes."
L42_1.m_Talk_FRA = L43_1
