L44_1.m_fWaitTime = 0
L45_1 = "CHIFUYU_NANA_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "하지만 머릿속으로 아무리 검을 휘두르고 몸을 움직여도,"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "だが、いくら頭の中で刀を振るい身体を動かしてみても、"
L44_1.m_Talk_JPN = L45_1
L45_1 = "But no matter how much I swiftly move and attack..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "可是無論我在腦海裡怎麼揮劍，怎麼移動身體，"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แต่ไม่ว่าข้าจะเคลื่อนไหวหรือโจมตีรวดเร็วเพียงใด..."
L44_1.m_Talk_THA = L45_1
L45_1 = "Nhưng dù có di chuyển và tấn công nhanh đến mức nào..."
L44_1.m_Talk_VTN = L45_1
L45_1 = "但是无论我在脑海中怎么挥剑或躲闪，"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Aber egal wie schnell ich mich auch bewege und mein Schwert schwinge ..."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Et pourtant, j'ai beau avoir tout essayé..."
L44_1.m_Talk_FRA = L45_1
