L46_1 = "CHIFUYU_NANA_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "도저히 그 공격을 받아 칠 수가 없어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "どうしてもあの攻撃を打ち返すことができない。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I couldn’t fight against her."
L45_1.m_Talk_ENG = L46_1
L46_1 = "就是無法抵擋她的攻擊。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ก็สู้นางไม่ได้เลย"
L45_1.m_Talk_THA = L46_1
L46_1 = "Mình vẫn không thể thắng nổi cô ta."
L45_1.m_Talk_VTN = L46_1
L46_1 = "都接不住她的攻击。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "So konnte ich sie dennoch nicht angreifen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Impossible de la battre."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "NANAHARA2_ACT1_INTERLUDE3@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5100108
L46_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "CHIFUYU_NANA_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "마치 내 움직임이 전부 읽히고 있는 것처럼……"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "まるで私の動きをすべて読まれているかのように……"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It was as if she already knew my next move..."
L46_1.m_Talk_ENG = L47_1
L47_1 = "彷彿她能夠看穿我一切的行動……"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ราวกับนางรู้ล่วงหน้าว่าข้าจะเคลื่อนไหวอย่างไรต่อ..."
L46_1.m_Talk_THA = L47_1
L47_1 = "Cứ như thể cô ta đã biết trước chiêu tiếp theo của mình vậy..."
L46_1.m_Talk_VTN = L47_1
L47_1 = "就好像她已经看穿了我的所有动作一样……"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Es war so, als wüsste sie bereits meinen nächsten Schritt ..."
L46_1.m_Talk_DEU = L47_1
L47_1 = "C'était comme si elle savait à l'avance ce que j'allais faire, avant même que je commence à attaquer..."
L46_1.m_Talk_FRA = L47_1
