L51_1 = "CHIFUYU_NANA_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "한심한 것. 이런 실력으로 어떻게 당주님을 지키겠단 말이냐?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "情けない。こんな実力でどうやって当主を守るというんだ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "How pathetic am I? How could I ever protect Lady Nanahara when I am so weak?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "沒出息的東西！這樣是要怎麼保護堂主？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "น่าสมเพชนักใช่ไหมข้านี่? ข้าอ่อนแอถึงเพียงนี้แล้วจะไปปกป้องท่านหญิงนานะฮาระได้อย่างไร?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Mình thật thảm hại nhỉ. Làm sao có thể bảo vệ được Tiểu Thư Nanahara khi mình quá yếu như vậy?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "真是不像话，凭这样的实力，你要如何保护家主？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wie erbärmlich bin ich eigentlich? Wie könnte ich die Anführerin jemals beschützen, wenn ich so schwach bin?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Pathétique. Comment pourrais-je protéger Dame Nanahara en étant aussi faible ?"
L50_1.m_Talk_FRA = L51_1
