L3_1 = "그때 도움을 받지 못했더라면 나는 지금쯤……"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "あの時助けてもらわなかったら今頃私は……"
L2_1.m_Talk_JPN = L3_1
L3_1 = "If it had not been for Miss Nao, I would have been–"
L2_1.m_Talk_ENG = L3_1
L3_1 = "那時候要是沒人出手相救，恐怕我現在已經……"
