L3_1 = "如果那时没有人出手相救，我现在应该……"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ohne die Unterstützung von Fräulein Nao wäre ich –"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Si madame Nao n'avait pas été là, nous aurions..."
