L4_1.m_Face = "UNIT_LAUGH"
L4_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L4_1.m_Pos = "C"
L5_1 = "그런 부러진 검으로 검술 연습을 하고 있는 게냐?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そのような折れた刀で剣術の修練をしておるのか？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "You’re training with a broken sword?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "你用那把斷劍在練習劍法嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "นี่เจ้ากำลังฝึกด้วยดาบหักรึ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Cô đang tập luyện với một thanh kiếm gãy sao?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "在用那种断掉的剑练习剑法吗？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Du trainierst mit einem kaputten Schwert?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Tu t'entraînes avec une épée brisée ?"
L4_1.m_Talk_FRA = L5_1
