L6_1 = "NANAHARA2_ACT1_INTERLUDE3@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5100108
L5_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
