L6_1 = "CHIFUYU_NANA_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "나오님……? 이런 곳엔 어쩐 일이십니까?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ナオ様……？　なにゆえこのようなところに？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Miss Nao...? What brings you here?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "奈緒……？你怎麼會在這裡？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ท่านนาโอะ...? มีเรื่องอะไรหรือคะ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Cô Nao...? Điều gì mang cô đến đây?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "奈绪大人……？您怎么会来这里？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Fräulein Nao ...? Was bringt Sie hierher?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Madame Nao... ? Que puis-je faire pour vous ?"
L5_1.m_Talk_FRA = L6_1
