L9_1 = "NANAHARA2_ACT1_INTERLUDE3@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 5100108
L8_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_LAUGH"
L8_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L8_1.m_Pos = "L"
L9_1 = "내가 그거 고쳐줄까?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "それ、わしが直してやろうか。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "You know, I could fix that for you."
L8_1.m_Talk_ENG = L9_1
L9_1 = "要我幫你修嗎？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "นี่ ข้าซ่อมให้ได้นะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Cô biết đấy, tôi có thể sửa nó cho cô."
L8_1.m_Talk_VTN = L9_1
L9_1 = "要我帮你修好它吗？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Soll ich es für dich reparieren?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Tu veux que je la répare pour toi ?"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "NANAHARA2_ACT1_INTERLUDE3@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5100108
L9_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_SURPRISE"
L10_1 = "CHIFUYU_NANA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "R"
L10_1 = "아닙니다. 은인 분에게 어찌 그런 수고를……"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "いいえ。恩人にそのような手間をおかけするわけには……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "No, but thank you. I could never ask for more from my savior–"
L9_1.m_Talk_ENG = L10_1
L10_1 = "不行，怎麼可以麻煩恩人……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ไม่เป็นไรแต่ก็ขอบคุณนะคะ ข้าคงไม่กล้าขออะไรจากผู้ที่ช่วยชีวิต–"
L9_1.m_Talk_THA = L10_1
L10_1 = "Không, nhưng cảm ơn cô. Tôi không bao giờ có thể đòi hỏi vị cứu tinh của mình nhiều hơn được-"
L9_1.m_Talk_VTN = L10_1
L10_1 = "不用，怎么好意思麻烦恩人受累……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Schon gut. Das würde niemals von meiner Retterin verlangen ..."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Non, je ne peux pas accepter. Nous vous devons déjà la vie..."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NANAHARA2_ACT1_INTERLUDE3@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 5100108
L10_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "UNIT_IDLE"
L10_1.m_Face = L11_1
L10_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L10_1.m_Pos = "L"
L11_1 = "나나하라의 검들은 모두 나와 제자들이 만든 것이다. 고치는 것쯤은 내게 식은 죽먹기지."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "七原の刀剣はすべてわしと弟子たちで作ったものじゃ。直すことくらい朝飯前じゃ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "All swords of the Nanahara family were made by me and my apprentices. Fixing one is nothing."
L10_1.m_Talk_ENG = L11_1
L11_1 = "七原的劍都是我和徒弟做的，修好它對我來說根本不費吹灰之力。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ดาบทุกเล่มของตระกูลนานะฮาระน่ะฝีมือข้าและลูกศิษย์ทั้งนั้น ซ่อมสักเล่มไม่ได้สำคัญอะไรหรอก"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tất cả những thanh kiếm của gia đình Nanahara đều do tôi và những người học việc của tôi làm ra. Sửa một chút không thành vấn đề."
L10_1.m_Talk_VTN = L11_1
L11_1 = "七原的剑全都是我和徒弟们锻造的。修好它对我来说是小菜一碟。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Alle Schwerter der Nanahara wurden von mir und meinen Lehrlingen hergestellt. Ich könnte es im Handumdrehen reparieren."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Sais-tu que toutes les lames de la famille Nanahara ont été forgées par mes disciples et moi-même ? Ça ne me prendra qu'une seconde."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NANAHARA2_ACT1_INTERLUDE3@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 5100108
L11_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "CHIFUYU_NANA_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "R"
L12_1 = "예……? 그게 정말입니까?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "なんと……？　それは本当ですか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Huh...? Is that really the truth?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "什麼……？真的嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "หา...? จริงเหรอคะ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Hả...? Đó là sự thật sao?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "什么……？真的吗？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wie bitte ...? Wirklich?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Comment... ? Est-ce la vérité ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "NANAHARA2_ACT1_INTERLUDE3@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5100108
L12_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_PRIDE"
L12_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L12_1.m_Pos = "L"
L13_1 = "그래, 그 검의 슴베 쪽을 확인해봐라."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "おう、その刀のなかごの部分を確認してみろ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Of course. Check the tang of your sword, will you?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "當然，你看看劍上面，"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ก็จริงนะสิ ลองดูกั่นดาบของเจ้าสิมั้ยล่ะ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tất nhiên rồi. Hãy kiểm tra chuôi kiếm xem sao?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "嗯，你仔细看看那把剑的剑柄。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Natürlich. Schau dir mal den Erl des Schwertes an."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Bien sûr. Regarde le pommeau un instant, tu veux bien ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "NANAHARA2_ACT1_INTERLUDE3@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5100108
L13_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L13_1.m_Pos = "L"
L14_1 = "내 제자들이 만든 검에는 전부 꽃이름을 붙여줬거든."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "わしの弟子たちが作った刀剣にはすべて花の名前をつけてある。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "All of the swords that my apprentices made were named after flowers."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我徒弟做的劍上都會刻上花的名字。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ดาบทุกเล่มที่ศิษย์ข้าตีจะตั้งชื่อตามดอกไม้"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tất cả kiếm mà đồ đề của tôi tạo ra đều được đặt tên theo các loài hoa."
L13_1.m_Talk_VTN = L14_1
L14_1 = "我的徒弟们锻造的剑，全都是花的名字。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Alle Schwerter, die meine Lehrlinge hergestellt haben, wurden nach Blumen benannt."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Toutes les lames forgées par mes disciples ont été nommées à partir de fleurs."
L13_1.m_Talk_FRA = L14_1
