L16_1 = "NANAHARA2_ACT1_INTERLUDE3@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5100108
L15_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_SURPRISE"
L16_1 = "CHIFUYU_NANA_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "……정말이군요. 수선이라고 새겨져 있습니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "……本当ですね。水仙と刻まれております。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "...You are right. I see \"Narcissus\" engraved on it."
L15_1.m_Talk_ENG = L16_1
L16_1 = "……是真的，上面刻著水仙。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "...จริงของท่าน ข้าเห็นคำว่า \"นาร์ซิสซัส\" สลักอยู่"
L15_1.m_Talk_THA = L16_1
L16_1 = "...Đúng vậy. Tôi thấy \"Narcissus\" được khắc trên đó."
L15_1.m_Talk_VTN = L16_1
L16_1 = "……是真的，上面刻着“水仙”两个字。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "... Sie haben recht. Das Wort „Narzisse“ ist eingraviert."
L15_1.m_Talk_DEU = L16_1
L16_1 = "... Vous dites vrai. L'inscription « Narcisse » y est gravée."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NANAHARA2_ACT1_INTERLUDE3@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 5100108
L16_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_LAUGH"
L16_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "호오, 제법 좋은 검을 쓰고 있었구나. 수선은 내 수제자가 만든 것이지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ほう、なかなか良いものを使っておるな。水仙はわしの一番弟子が作ったものじゃ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Oh? That’s a fine one you’ve got. Narcissus was made by my best pupil."
L16_1.m_Talk_ENG = L17_1
L17_1 = "喔呵，你拿到一把好劍呢，水仙是我的大徒弟做的。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "โอ้? ได้เล่มดีเลยนะเจ้าน่ะ นาร์ซิสซัสนี่ผลงานศิษย์มือดีที่สุดของข้า"
L16_1.m_Talk_THA = L17_1
L17_1 = "Oh? Cô có một thanh kiếm tốt đấy. Narcissus do đồ đệ giỏi nhất của tôi tạo ra."
L16_1.m_Talk_VTN = L17_1
L17_1 = "噢噢，看来你拿着一把好剑呢。那是我大徒弟锻造的。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Oh? Du nutzt ein ziemlich gutes Schwert. Die „Narzisse“ wurde nämlich von meinem besten Lehrling hergestellt."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Oh ? C'est une bien belle lame que tu as là. Narcisse est l'œuvre de mon meilleur disciple."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "NANAHARA2_ACT1_INTERLUDE3@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5100108
L17_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "녀석에게 쓰고 싶은 글귀가 있으면 남겨두라고 했는데, 혹시 뭐라고 적혀있느냐?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "やつに刻みたい言葉があれば残しておけと言ったのじゃが、何と書いてあるのかのう？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I told her to engrave whatever text she wished to leave behind. What does it say?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "我跟他說想說什麼都可以刻在劍上，上面有寫什麼話嗎？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ข้าบอกให้นางสลักข้อความอะไรที่อยากสั่งเสียไว้ มันเขียนว่าอะไรล่ะ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi bảo con bé cứ khắc bất kỳ văn tự nào nó muốn. Trên đó nói gì?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "我跟那家伙说过，如果有想写的字就刻上去。上面还有什么字么？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich sagte ihr, sie solle den Text eingravieren, den sie hinterlassen wollte. Was steht dort geschrieben?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Conformément à mes instructions, il aura également laissé sa petite griffe derrière, une phrase qui avait du sens pour lui."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "NANAHARA2_ACT1_INTERLUDE3@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 5100108
L18_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "CHIFUYU_NANA_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "<color=#ffd34c>땅딸보 꼰대 스승 언젠가 짓밟고 만다</color>……"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "<color=#ffd34c>チビくそババァの師匠、いつか踏みつけてやる</color>……"
L18_1.m_Talk_JPN = L19_1
L19_1 = "<color=#ffd34c>I swear I’m going to crush my midget of a master someday</color>..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "<color=#ffd34c>矮冬瓜老太婆師父，總有一天我會贏過你</color>……"
L18_1.m_Talk_TWN = L19_1
L19_1 = "<color=#ffd34c>สาบานเลยว่าสักวันข้าจะขยี้อาจารย์ร่างแคระของตนให้ปี้ป่น</color>"
L18_1.m_Talk_THA = L19_1
L19_1 = "<color=#ffd34c>Tôi thề một ngày nào đó tôi sẽ nghiền nát sư phụ lùn tịt của mình</color>..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "<color=#ffd34c>总有一天，我要把老顽固师傅踩在脚下</color>……"
L18_1.m_Talk_SCN = L19_1
L19_1 = "<color=#ffd34c>Ich schwöre, ich werde eines Tages meine mickrige Meisterin zerquetschen</color> ..."
L18_1.m_Talk_DEU = L19_1
L19_1 = "« <color=#ffd34c>Cette cornue arrogante, je lui pisse à la raie</color>... »"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
