L21_1 = "NANAHARA2_ACT1_INTERLUDE3@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5100108
L20_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "CHIFUYU_NANA_NULL_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "라고 되어있습니다만."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "と、刻まれていますが。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "That is what it says."
L20_1.m_Talk_ENG = L21_1
L21_1 = "上面是這樣寫的。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ข้อความว่าเช่นนี้นค่ะ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Nó viết thế đó."
L20_1.m_Talk_VTN = L21_1
L21_1 = "这是剑上的字。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "... Das steht dort geschrieben."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Voilà ce que ça dit."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "NANAHARA2_ACT1_INTERLUDE3@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5100108
L21_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_LAUGH"
L21_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Crash = 20
L22_1 = "……으하하! 스승을 뛰어넘고자 하는 제자의 훌륭한 자세로군!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "……ははは！　師匠を超えようとする弟子の立派な心がけじゃ！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "...Ha ha ha! That’s the spirit! Surpass your master!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "……哈哈哈！原來是想要超越師父嗎？非常棒的宣告！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "...ฮ่า ฮ่า ฮ่า! ต้องอย่างนี้สิ! แซงหน้าอาจารย์ตน!"
L21_1.m_Talk_THA = L22_1
L22_1 = "...Ha ha ha! Quả là có chí khí! Vượt qua cả sư phụ!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "……呃哈哈！不想超越师傅的徒弟就不是好徒弟！不错！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "... Hahaha! Das ist genau die richtige Einstellung! Der Lehrling sollte eines Tages seinen Meister übertreffen!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "... Bwa ha ha ! L'élève qui veut dépasser le maître, hein ? J'aime l'esprit !"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NANAHARA2_ACT1_INTERLUDE3@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5100108
L22_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_PRIDE"
L22_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "뭐, 그 소원은 결국 이뤄지지 못했지만 말이지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "まあ、その願いは結局叶わなかったがな。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Too bad the wish never came true, though."
L22_1.m_Talk_ENG = L23_1
L23_1 = "不過這句話終究沒有成真。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แต่ก็น่าเสียดายที่ปรารถนานั้นไม่เคยได้เป็นจริง"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tuy nhiên, thật tệ là điều ước đó không bao giờ thành hiện thực."
L22_1.m_Talk_VTN = L23_1
L23_1 = "嗯，虽然这个愿望最后也没能实现。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Schade, dass der Wunsch nie in Erfüllung gegangen ist."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Malheureusement pour lui, il n'a jamais pu réaliser son souhait."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
