L24_1.m_Pos = "C"
L25_1 = "내가 그 검을 고치는 동안 너는 이걸로 연습이나 해라."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "わしがその刀を直す間、お主はこれで練習でもしていろ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Here, practice with this while I fix your sword."
L24_1.m_Talk_ENG = L25_1
L25_1 = "在我替你修劍的時候，你先用這把劍練習吧。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เอ้า เอานี่ไปฝึกระหว่างข้าซ่อมดาบเจ้าซะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Đây, hãy luyện tập với cái này trong khi tôi sửa kiếm cho cô."
L24_1.m_Talk_VTN = L25_1
L25_1 = "拿去，我给你修的时候，你先用这把剑练习吧。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Übe damit, während ich dein Schwert repariere."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Tiens. Prends ça pendant que je répare ton arme."
L24_1.m_Talk_FRA = L25_1
