L27_1 = "CHIFUYU_NANA_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "이건…… 특이한 색을 가진 검이로군요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "これは……独特な色をした刀ですね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "This... has an interesting sheen to it."
L26_1.m_Talk_ENG = L27_1
L27_1 = "這把劍……顏色好特別。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "นี่มัน... ส่องประกายน่าสนใจมากค่ะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Cái này... có độ lấp lánh rất thú vị."
L26_1.m_Talk_VTN = L27_1
L27_1 = "这把剑……颜色好特别。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Das ... hat einen interessanten Glanz."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Cette lame... quelle couleur fascinante."
L26_1.m_Talk_FRA = L27_1
