L31_1.m_Pos = "L"
L32_1 = "흐음…… 역시 휘두르는 것까지는 못하는 건가?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ふむ……やはり振るうことまでは無理かのう。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Hmm... I guess using it properly is out of the question."
L31_1.m_Talk_ENG = L32_1
L32_1 = "嗯……揮不動嗎？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "อืมม... ท่าว่าจะใช้ให้ดียังไงยิ่งไม่ต้องพูดถึงเลย"
L31_1.m_Talk_THA = L32_1
L32_1 = "Hmm... Tôi đoán sử dụng nó cho đúng là điều không phải bàn cãi."
L31_1.m_Talk_VTN = L32_1
L32_1 = "嗬嗯……果然挥不动吗？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Hmm ... Du kannst es ja wirklich nicht einmal schwingen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Hmm... alors tu peux la soulever, mais pas t'en servir..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "NANAHARA2_ACT1_INTERLUDE3@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5100108
L32_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_IDLE"
L32_1.m_Face = L33_1
L33_1 = "CHIFUYU_NANA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "R"
L33_1 = "나오님, 이 검은 대체……?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ナオ様、この刀はいったい……？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Miss Nao, what is this sword...?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "奈緒，這把劍究竟是……？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ท่านนาโอะคะ ดาบนี่มันอะไรกัน?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cô Nao, thanh kiếm này là gì...?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "奈绪大人，这把剑究竟……？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Fräulein Nao, was ist das für ein Schwert ...?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Madame Nao, quelle est cette épée... ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NANAHARA2_ACT1_INTERLUDE3@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5100108
L33_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L33_1.m_Pos = "L"
L34_1 = "평범한 인간은 그걸 손에 쥐는 것만으로도 힘겨워하지."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "普通の人間ならばそれを手に持っているだけでもつらい。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Normal humans can’t even bear holding it."
L33_1.m_Talk_ENG = L34_1
L34_1 = "一般人光是要拿起這把劍都很費力，"
L33_1.m_Talk_TWN = L34_1
L34_1 = "คนธรรมดาน่ะจะถือยังไม่ไหวเลยนะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Người bình thường thậm chí không thể cầm nổi nó đâu."
L33_1.m_Talk_VTN = L34_1
L34_1 = "普通人连把它拿在手里都很吃力。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Gewöhnliche Menschen sind nicht einmal in der Lage, es zu halten."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Un être humain ordinaire n'aurait même pas été capable de la brandir comme tu le fais."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "NANAHARA2_ACT1_INTERLUDE3@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5100108
L34_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L34_1.m_Pos = "L"
L35_1 = "그걸 가볍게 들 수 있다는 건, 네가 나나하라류의 무사로서 최소한의 자격은 갖추었다는 뜻이다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "それをひょいと持ち上げられるということは、お主が七原流の武士として最低限の資格は持っているという意味じゃ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "The fact that you’re able to hold it around freely means that you passed the minimum requirements of becoming a Nanahara Style warrior."
L34_1.m_Talk_ENG = L35_1
L35_1 = "如果可以輕鬆拿起這把劍，就表示你有成為七原流武士的最基本資格。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "การที่เจ้าถือมันไปมาได้ก็แปลว่าผ่านคุณสมบัติขั้นต่ำของการเป็นอาจารย์วิชาต่อสู้สายนานะฮาระแล้ว"
L34_1.m_Talk_THA = L35_1
L35_1 = "Việc cô có thể cầm được nó một cách thoải mái đã cho thấy cô vượt qua yêu cầu tối thiểu để trở thành cao thủ Trường Phái Nanahara rồi."
L34_1.m_Talk_VTN = L35_1
L35_1 = "可以轻松拿起这把剑，就意味着你具备了七原流武士最基本的资格。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Die Tatsache, dass du es halten kannst, bedeutet, dass du die Mindestanforderungen erfüllt hast, um eine Kriegerin des Nanahara-Stils zu werden."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ce qui signifie que tu disposes des aptitudes nécessaires pour devenir une épéiste du style Nanahara."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NANAHARA2_ACT1_INTERLUDE3@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5100108
L35_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_SURPRISE"
L36_1 = "CHIFUYU_NANA_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "R"
L36_1 = "나오님께서 나나하라류를 어찌 아시는지요?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ナオ様はどうして七原流をご存じなのですか？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "How are you aware of Nanahara Style, Miss Nao?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "你怎麼會知道七原流？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ทราบเรื่องนี้ได้ยังไงกันคะ ท่านนาโอะ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Sao cô biết được điều đó, Cô Nao?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "奈绪大人怎么会知道七原流？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Woher kennen Sie den Nanahara-Stil, Fräulein Nao?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Le style Nanahara ? Mais comment savez-vous... ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA2_ACT1_INTERLUDE3@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5100108
L36_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_LAUGH"
L36_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L36_1.m_Pos = "L"
L37_1 = "그야 내가 고르디우스의 대장 노릇을 맡을 적부터 그 검술을 배운 녀석들만 데리고 다녔으니 그렇지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そりゃあ、わしがゴルディウスの隊長をやっていた頃からその剣術を身につけたやつらだけを連れていたからな。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "That’s because I used to hang out with a bunch of Nanahara warriors ever since I was Commander at the Gordias Division."
L36_1.m_Talk_ENG = L37_1
L37_1 = "因為我擔任戈爾迪亞的戰隊長時，我帶的傢伙都學過這套劍法。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เพราะข้าเคยใช้เวลากับอาจารย์นานะฮาระมาหลายคนตั้งแต่ตอนเป็นผู้บัญชาการกองพลกอร์เดียสไงล่ะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đó là bởi vì tôi đã từng đồng hành với một nhóm cao thủ Trường Phái Nanahara khi tôi còn làm tổng tư lệnh ở Sư đoàn Gordias."
L36_1.m_Talk_VTN = L37_1
L37_1 = "那是因为我从担任戈尔迪亚的战队长时，就带着你们学习那个剑法了。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Das liegt daran, dass ich, seit ich die Kommandantin der Gordias-Division war, nur diejenigen mitgenommen habe, die die Schwertkunst erlernt hatten."
L36_1.m_Talk_DEU = L37_1
L37_1 = "À l'époque où j'étais à la tête de la Division Gordias, tous mes lieutenants en faisaient partie."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA2_ACT1_INTERLUDE3@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5100108
L37_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "CHIFUYU_NANA_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "R"
L38_1 = "예? 하지만 고르디우스는 초대전대장이 사라진 뒤로 계속 공석이었다고 들었습니다만……?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "え？　ですがゴルディウスは初代戦隊長が行方不明になった後からずっと空席だと聞きましたが……？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Huh? But I heard that the commander’s seat remained empty after the first one disappeared..."
L37_1.m_Talk_ENG = L38_1
L38_1 = "什麼？可是我聽說戈爾迪亞自從初代戰隊長消失後，就一直是從缺的狀態……？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "หา? แต่ได้ยินว่าตำแหน่งผู้บัญชาการว่างลงตั้งแต่ผู้บัญชาการคนแรกหายไปแล้วนี่คะ..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Huh? Nhưng tôi nghe nói chiếc ghế tổng tư lệnh vẫn còn bỏ trống sau khi người đầu tiên biến mất..."
L37_1.m_Talk_VTN = L38_1
L38_1 = "什么？但是我听说戈尔迪亚从第一任队长消失后就一直是空缺的……？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Was? Aber ich habe gehört, dass der Sitz des Gordias Kommandanten leer blieb, nachdem der erste verschwunden war ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "À la tête de la Division Gordias ? Mais j'ai entendu dire que le poste de commandant est resté vacant depuis le départ de la première commandante..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
