L41_1 = "NANAHARA2_ACT1_INTERLUDE3@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 5100108
L40_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_DESPAIR"
L41_1 = "CHIFUYU_NANA_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "R"
L41_1 = "그런 줄도 모르고 감히 존함을 읊는 무례를 범했군요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "知らぬこととはいえ、ご尊名でお呼びした無礼をお許しください。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I apologize for my discourtesy."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我竟敢直呼您的名諱，請原諒我的失禮。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ขออภัยที่เสียมารยาทนะคะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tôi xin lỗi vì sự bất lịch sự của mình."
L40_1.m_Talk_VTN = L41_1
L41_1 = "我之前都不知道，对您多有冒犯。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ich entschuldige mich für meine Unhöflichkeit."
L40_1.m_Talk_DEU = L41_1
L41_1 = "... Je vois. Veuillez excuser mes manières."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "NANAHARA2_ACT1_INTERLUDE3@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5100108
L41_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "UNIT_IDLE"
L41_1.m_Face = L42_1
L42_1 = "CHIFUYU_NANA_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "R"
L42_1 = "전대장 어르신…… 이라고 불러드리면 되겠습니까?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "戦隊長様……とお呼びしたらいいのでしょうか。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Should I call you... Commander?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "戰隊長大人……這樣稱呼您可以嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ขอข้าเรียกว่า... ผู้บัญชาการได้มั้ยคะ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi có nên gọi cô là... tổng tư lệnh không?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "战队长大人……这样称呼您可以吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Soll ich Sie von nun an „Kommandantin“ nennen?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Dois-je vous appeler... commandante en chef ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "NANAHARA2_ACT1_INTERLUDE3@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5100108
L42_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_PRIDE"
L42_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L42_1.m_Pos = "L"
L43_1 = "흥, 이제 와서 늙은이 취급할 셈이냐? 계속 나오님이라고 불러라."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ふん、今更年寄り扱いするつもりか？　そのままナオ様と呼べ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Tsk, You sound like you’re caught up on my age, child. Call me Nao."
L42_1.m_Talk_ENG = L43_1
L43_1 = "哼，你現在是想把我叫老嗎？一樣叫我奈緒大人就好。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ชิ พูดจาอย่างกับรู้ว่าข้าอายุเท่าไหร่เลยยัยเด็กนี่ เรียกข้านาโอะเถอะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Chậc, cô nói cứ như bằng tuổi tôi ấy, nhóc. Gọi tôi là Nao đi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "呃，怎么感觉是把我叫老了呢？还是继续叫我奈绪大人吧。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hmpf, machst du dir etwa Sorgen um mein Alter? Nenn mich einfach weiterhin „Fräulein Nao“."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Tss, c'est un peu tard pour ça. Madame Nao, ça fera l'affaire."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "NANAHARA2_ACT1_INTERLUDE3@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 5100108
