L47_1 = "NANAHARA2_ACT1_INTERLUDE3@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5100108
L46_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "UNIT_IDLE"
L46_1.m_Face = L47_1
L46_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = "그건 그렇고, 네 녀석은 역신베기에 대해 들어봤느냐?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "それはそうと、お主は大蛇薙剣について知っているか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "That aside, are you familiar with Orochinagi?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "先不說這個，你聽過瘟神斬嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ว่าแต่ว่า เจ้าคุ้นชื่อโอโรจินางิบ้างหรือไม่?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ngoài chuyện đó ra, cô có biết về Orochinagi không?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "先不说这个了，你听说过瘟神斩吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Übrigens, was weißt du über das Orochinagi?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Dis-moi, as-tu entendu parler de l'Orochinagi ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "NANAHARA2_ACT1_INTERLUDE3@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 5100108
L47_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "UNIT_IDLE"
L47_1.m_Face = L48_1
L48_1 = "CHIFUYU_NANA_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "아는 것은 많지 않으나…… 역신을 벨 수 있는 검이라고 들었습니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "そう詳しくはありませんが……疫病神を斬ることができる剣だと聞きました。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I don’t know a lot about it... but I heard that it is the sword that can slay the Plague God."
L47_1.m_Talk_ENG = L48_1
L48_1 = "我知道的不多……只知道是可以斬殺瘟神的劍。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ข้าก็ไม่ค่อยรู้นักค่ะ... แต่ได้ยินมาว่าเป็นดาบที่สังหารเทพภัยพิบัติได้"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi không biết nhiều về nó là đằng khác... nhưng tôi nghe nói rằng đó là thanh kiếm có thể giết chết Thần Bệnh Dịch."
L47_1.m_Talk_VTN = L48_1
L48_1 = "虽然知道的不多……但是我听说那是可以斩杀瘟疫之神的剑。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich weiß nicht viel darüber ... aber ich habe gehört, dass es das Schwert ist, das den Gott der Verwesung töten kann."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je ne sais que peu de choses à son sujet... si ce n'est qu'il s'agit d'une lame qui serait capable de tuer le Dieu du Fléau."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "NANAHARA2_ACT1_INTERLUDE3@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5100108
L48_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "그래."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そうじゃ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Right."
L48_1.m_Talk_ENG = L49_1
L49_1 = "沒錯。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ใช่"
L48_1.m_Talk_THA = L49_1
L49_1 = "Đúng vậy."
L48_1.m_Talk_VTN = L49_1
L49_1 = "是的。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Genau."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Correct."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "NANAHARA2_ACT1_INTERLUDE3@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 5100108
L49_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "그리고 그 검이 바로 역신베기의 초석인 명부검이다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そしてお主の持つその刀が大蛇薙剣の基礎となる冥府剣じゃ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "The sword you are holding right now is the foundation, the Nether God’s Sword."
L49_1.m_Talk_ENG = L50_1
L50_1 = "而你手上那把劍叫作冥府劍，它是完成瘟神斬不可或缺的材料。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ดาบที่เจ้าถืออยู่ตอนนี้ก็คือรากฐานของมัน ดาบยมราช"
L49_1.m_Talk_THA = L50_1
L50_1 = "Thanh kiếm mà cô đang cầm bây giờ chỉ là cơ sở thôi, Thanh Kiếm Của Thần Âm Ty."
L49_1.m_Talk_VTN = L50_1
L50_1 = "而这把剑就是瘟神斩的基础——冥剑。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Das Schwert, das du gerade in der Hand hältst, ist das Fundament des Orochinagis."
L49_1.m_Talk_DEU = L50_1
L50_1 = "L'épée que tu as dans les mains n'est autre que sa base, la Lame du Néant."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "NANAHARA2_ACT1_INTERLUDE3@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5100108
L50_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L50_1.m_Pos = "C"
L51_1 = "옛 명부신께서 휘두르던 검을 내 선조들이 복원한 것이지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "昔、冥府の神が持っていた剣を、わしの先祖が復元したのだ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "It belonged to the Nether God, now restored by my ancestors."
L50_1.m_Talk_ENG = L51_1
L51_1 = "它原是冥府神使用過的劍，後來我的祖先將其復原。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "มันเคยเป็นของยมราช ซึ่งตอนนี้บรรพบุรุษของข้าเป็นผู้ฟื้นฟูมา"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nó từng thuộc về Thần Âm Ty, giờ đã được tổ tiên của tôi phục hồi."
L50_1.m_Talk_VTN = L51_1
L51_1 = "它原是冥神使用过的剑，后来由我的先祖们将它复原。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Es gehörte dem Gott des Jenseits und wurde von meinen Vorfahren wiederhergestellt."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Elle appartenait jadis au Dieu du Néant, avant d'être restaurée par mes ancêtres."
L50_1.m_Talk_FRA = L51_1
