L2_1 = "NANAHARA2_ACT1_INTERLUDE3@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 5100108
L1_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_SURPRISE"
L2_1 = "CHIFUYU_NANA_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "예……? 그럼 이것을 휘두를 수만 있으면 역신을 막을 수 있는 겁니까?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "はい……？　ではこれを振るうことができれば、疫病神の復活を阻止することができるのですか？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Huh...? Does that mean that we can stop the Plague God, once I am able to use this?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "什麼……？那意思就是，只要能揮動這把劍，就可以抵擋瘟神嗎？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "หา...? หมายความว่าข้าใช้ดาบนี่ได้เมื่อไหร่ ก็จะยับยั้งเทพภัยพิบัติได้หรือคะ?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Hả...? Điều đó có nghĩa là chúng ta có thể ngăn chặn Thần Bệnh Dịch, sau khi tôi có thể sử dụng nó sao?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "也、也就是说……？只要能挥舞这把剑，就能阻止瘟疫之神的意思吗？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Häh ...? Bedeutet das, dass wir den Gott der Verwesung stoppen können, sobald ich in der Lage bin, dieses Schwert zu nutzen?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Hein...? Alors si j'arrive à la maîtriser, je pourrai arrêter le Dieu du Fléau ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NANAHARA2_ACT1_INTERLUDE3@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5100108
L2_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_PRIDE"
L2_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L2_1.m_Pos = "C"
L3_1 = "순진하구나. 그게 말처럼 쉬우면 누가 역신을 두려워하겠냐?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ウブじゃのう。そんなに容易いことなら疫病神を恐れる者はおるまい。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Naive much, are you? It’s easier said than done."
L2_1.m_Talk_ENG = L3_1
L3_1 = "真是天真，要是有這麼容易，還有誰會怕瘟神？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ไร้เดียงสาเสียงจริงนะเจ้า แค่พูดมันก็ง่ายอยู่หรอก"
L2_1.m_Talk_THA = L3_1
L3_1 = "Cô ngây thơ quá nhỉ? Nói thì dễ hơn làm."
L2_1.m_Talk_VTN = L3_1
L3_1 = "你太天真了。如果像你说的那么容易，谁还会惧怕瘟疫之神？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Du bist recht naiv. Es ist leichter gesagt als getan, den Gott der Verwesung zu bezwingen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Quelle naïveté, c'est adorable. Plus facile à dire qu'à faire, tu ne crois pas ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
