L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L4_1.m_Pos = "C"
L5_1 = "역신베기를 완성하기 위해서는 그 명부검에 어울리는 나나하라 혈통의 영혼이 필요하다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "大蛇薙剣を完成させるためには、冥府剣に相応しい七原の血統を持つ魂が必要なんじゃ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "To complete Orochinagi, we need the soul of a rightful Nanahara descendant."
L4_1.m_Talk_ENG = L5_1
L5_1 = "完成瘟神斬還需要是七原血統的靈魂。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "จะสร้างโอโรจินางิสำเร็จ เราต้องใช้วิญญาณของผู้สืบสายเลือดนานะฮาระโดยชอบธรรม"
L4_1.m_Talk_THA = L5_1
L5_1 = "Để hoàn thành Orochinagi, chúng ta cần linh hồn của một hậu duệ hợp pháp của Nanahara."
L4_1.m_Talk_VTN = L5_1
L5_1 = "为了完成瘟神斩，需要与这把冥剑相配的七原血统的灵魂。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Um das Orochinagi zu vollenden, brauchen wir die Seele eines rechtmäßigen Nachkommens der Nanahara."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Pour achever l'Orochinagi, j'ai besoin de l'âme d'une véritable descendante de la lignée des Nanahara."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "NANAHARA2_ACT1_INTERLUDE3@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5100108
L5_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "허나 아직도 그 조건에 맞는 영혼은 나타난 적이 없다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "だが、いまだにその条件に合う魂は現れておらん。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "However, there were none so far."
L5_1.m_Talk_ENG = L6_1
L6_1 = "不過，到目前為止，還沒有符合條件的靈魂出現過。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ซึ่งจนบัดนี้ยังไม่มีเลย"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tuy nhiên, cho đến giờ vẫn chưa có ai."
L5_1.m_Talk_VTN = L6_1
L6_1 = "但是到目前为止，还没出现过符合这个条件的灵魂。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Allerdings gab es bisher noch keine."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Et jusqu'à maintenant, il n'y en avait pas. Pas qui puisse manier le sabre, du moins."
L5_1.m_Talk_FRA = L6_1
