L7_1 = "CHIFUYU_NANA_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "그렇다면 오늘 이곳에 오신 이유 또한……"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "それでは、今日ここに来られた理由も……"
L6_1.m_Talk_JPN = L7_1
L7_1 = "That means... the reason why you are here is..."
L6_1.m_Talk_ENG = L7_1
L7_1 = "所以您今日造訪的目的就是……"
L6_1.m_Talk_TWN = L7_1
L7_1 = "หมายความว่า... ที่ท่านมาที่นี่ก็เพราะ..."
L6_1.m_Talk_THA = L7_1
L7_1 = "Điều đó có nghĩa là... lý do khiến cô ở đây là..."
L6_1.m_Talk_VTN = L7_1
L7_1 = "所以您今天来到联盟的理由也是……"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Sie sind also heute hier, um ..."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Mais alors, vous êtes ici pour..."
L6_1.m_Talk_FRA = L7_1
