L8_1 = "NANAHARA2_ACT1_INTERLUDE3@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 5100108
L7_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L7_1.m_bWaitClick = true
