L7_1.m_Face = "UNIT_LAUGH"
L7_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "그래, 이 명부검을 역신베기로 완성하기 위해서지."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "うむ。この冥府剣を大蛇薙剣に仕上げるためじゃ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Yes. It is to change the Nether God’s Sword into Orochinagi, its ultimate form."
L7_1.m_Talk_ENG = L8_1
L8_1 = "沒錯，就是要完成拿冥府劍完成瘟神斬。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ใช่ เพื่อเปลี่ยนดาบยมราชเป็นโอโรจินางิ รูปแบบสุดท้ายของมัน"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đúng. Đó là thay đổi thanh kiếm của Thần Âm Ty thành Orochinagi, dạng tối thượng."
L7_1.m_Talk_VTN = L8_1
L8_1 = "是的，为了用这把冥剑完成弑神剑。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Genau. Um das Schwert des Gottes des Jenseits in seine ultimative Form, das Orochinagi zu verwandeln."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Oui. Pour donner à la Lame du Néant sa véritable forme : pour l'éveiller en Orochinagi."
L7_1.m_Talk_FRA = L8_1
