L10_1 = "CHIFUYU_NANA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "저에게 이 검을 쥐어 주신 것에는 그럴 만한 이유가 있을 터……"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "私にこの剣を握らせたのには相応の理由があるはず……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "There must be a reason why you have handed me this sword..."
L9_1.m_Talk_ENG = L10_1
L10_1 = "那您把這把劍交給我的原因是……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ท่านย่อมไม่ได้มอบดาบนี่ให้ข้าโดยไม่มีเหตุผลอยู่แล้วค่ะ..."
L9_1.m_Talk_THA = L10_1
L10_1 = "Hẳn có lý do khiến cô trao cho tôi thanh kiếm này."
L9_1.m_Talk_VTN = L10_1
L10_1 = "那您把这柄剑交给我的理由……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Es muss einen Grund dafür geben, warum Sie mir dieses Schwert gegeben haben ..."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Puisque vous m'avez remis cette épée..."
