L11_1 = "NANAHARA2_ACT1_INTERLUDE3@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 5100108
L10_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "CHIFUYU_NANA_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "혹 제가 그에 걸맞은 조건을 가진 사람입니까?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "もしや私が冥府剣に相応しい条件を持っている者なのでしょうか？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Am I the rightful one?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "難道我是符合資格的人選嗎？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ข้าคือผู้มีสิทธิ์โดยชอบธรรมหรือคะ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi là người hợp lệ phải không?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "我便是那个符合条件的人？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Erfülle ich etwa die Bedingungen?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Cela signifie-t-il que vous m'en jugez légitime ?"
L10_1.m_Talk_FRA = L11_1
