L12_1 = "NANAHARA2_ACT1_INTERLUDE3@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 5100108
L11_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L11_1.m_bWaitClick = true
