L11_1.m_Face = "UNIT_LAUGH"
L11_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "흐흥, 반은 맞고 반은 틀렸다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ふふん、半分当たっているが半分は外れているのう。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Hmm. Kind of, but not quite."
L11_1.m_Talk_ENG = L12_1
L12_1 = "嗯哼，你只說對一半。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "อืม ก็คล้ายๆ แต่ไม่เชิง"
L11_1.m_Talk_THA = L12_1
L12_1 = "Hmm. Đại loại thế, nhưng không hẳn."
L11_1.m_Talk_VTN = L12_1
L12_1 = "对咯，不过只对了一半。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Hmm. Teilweise, aber nicht ganz."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Hmm. À moitié légitime, disons."
L11_1.m_Talk_FRA = L12_1
