L12_1.m_Pos = "C"
L13_1 = "명부신께서 말씀하시길……"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "冥府の神は……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "As the Nether God once said..."
L12_1.m_Talk_ENG = L13_1
L13_1 = "冥府神說……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ดังที่ครั้งหนึ่งยมราชกล่าวไว้..."
L12_1.m_Talk_THA = L13_1
L13_1 = "Như Thần Âm Ty đã từng nói ..."
L12_1.m_Talk_VTN = L13_1
L13_1 = "冥神说过……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Wie der Gott des Jenseits einst sagte ..."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Pour reprendre les mots du Dieu du Néant lui-même..."
L12_1.m_Talk_FRA = L13_1
