L14_1 = "NANAHARA2_ACT1_INTERLUDE3@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5100108
