L13_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L13_1.m_Pos = "C"
L13_1.m_Crash = 20
L14_1 = "<color=#ffd34c>역신베기는 두려워 할 죽음이 없는 무사가 자신의 목숨을 바쳐 완성되리라.</color>"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "<color=#ffd34c>大蛇薙剣は恐れるべき死のない武士が自らの命を捧げることにより完成するであろう。</color>"
L13_1.m_Talk_JPN = L14_1
L14_1 = "<color=#ffd34c>Completed shall Orochinagi be, with the life of a warrior unafraid of all death.</color>"
L13_1.m_Talk_ENG = L14_1
L14_1 = "<color=#ffd34c>瘟神斬必須由無懼死亡的武士獻上自己的性命才能完成。</color>"
L13_1.m_Talk_TWN = L14_1
L14_1 = "<color=#ffd34c>โอโรจินางิจักสมบูรณ์ได้ก็ด้วยชีวิตของนักรบผู้ไม่กริ่งเกรงมฤตยูทั้งปวง</color>"
L13_1.m_Talk_THA = L14_1
L14_1 = "<color=#ffd34c>Orochinagi sẽ hoàn thành, bằng sinh mạng của một chiến binh không sợ hãi trước cái chết. </color>"
L13_1.m_Talk_VTN = L14_1
L14_1 = "<color=#ffd34c>瘟神斩需要无惧死亡的武士之生命才能完成。</color>"
L13_1.m_Talk_SCN = L14_1
L14_1 = "<color=#ffd34c>Das Orochinagi wird mit dem Leben eines Kriegers vollendet, der den eigenen Tod nicht fürchtet.</color>"
L13_1.m_Talk_DEU = L14_1
L14_1 = "« <color=#ffd34c>L'Orochinagi ne sera véritablement achevé que par le sacrifice d'un guerrier qui ne craint pas la mort.</color> »"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
