L16_1 = "NANAHARA2_ACT1_INTERLUDE3@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5100108
L15_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "이곳에 오기 전까지 어느 정도 기대를 갖고 있던 건 사실이다만……"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "いくばくかの期待を持ってここへやって来はしたが……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I admit, I did have high hopes before arriving here..."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我今日確實是帶著某種程度的期待而來……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ข้ายอมรับนะ ว่าก่อนมานี่ข้าหวังไว้สูงทีเดียว..."
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi thừa nhận, tôi đã có nhiều hy vọng trước khi đến đây..."
L15_1.m_Talk_VTN = L16_1
L16_1 = "来这里之前，我确实对你有过期待……"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich gebe zu, ich hatte große Hoffnungen, bevor ich hierher kam ..."
L15_1.m_Talk_DEU = L16_1
L16_1 = "J'avais de l'espoir en venant ici, c'est vrai..."
L15_1.m_Talk_FRA = L16_1
