L16_1.m_Pos = "C"
L17_1 = "너에겐 어울리지 않는 역할이다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "お主には似合わぬ役割じゃ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "But it is not your role."
L16_1.m_Talk_ENG = L17_1
L17_1 = "不過你不是對的人。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แต่มันไม่ใช่หน้าที่เจ้า"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nhưng vai trò của cô không phải là thế."
L16_1.m_Talk_VTN = L17_1
L17_1 = "但你不是对的人。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Aber du bist nicht für diese Rolle bestimmt."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Mais ce rôle, ce n'est pas le tiens."
L16_1.m_Talk_FRA = L17_1
