L19_1 = "NANAHARA2_ACT1_INTERLUDE3@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 5100108
L18_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "CHIFUYU_NANA_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "저는 당주님을 지킬 수만 있다면, 죽음 같은 건 두렵지 않습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "私は当主を守れるのなら、死など怖くありません。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "As long as I can protect Lady Nanahara, death is meaningless to me."
L18_1.m_Talk_ENG = L19_1
L19_1 = "只要能保護堂主，要我犧牲性命我也不怕。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ตราบใดที่ข้าปกป้องท่านหญิงนานะฮาระได้ ความตายก็ไม่มีความหมายอะไรค่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Miễn là tôi có thể bảo vệ Tiểu Thư Nanahara, chết cũng không sao."
L18_1.m_Talk_VTN = L19_1
L19_1 = "我并不畏惧死亡，只要能保护家主就行。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Solange ich die Anführerin beschützen kann, ist der Tod für mich bedeutungslos."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Si c'est pour protéger Dame Nanahara, je suis prête à offrir ma vie s'il le faut."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "NANAHARA2_ACT1_INTERLUDE3@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 5100108
L19_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_PRIDE"
L19_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L19_1.m_Pos = "C"
L20_1 = "네가 그 가면 쓴 계집과 싸울 때 이미 확신했다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "お主があの仮面の娘と戦った時に確信したのじゃ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "It was apparent already when you were fighting that masked girl."
L19_1.m_Talk_ENG = L20_1
L20_1 = "在你和那個戴面具的丫頭對打時我就知道，"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เห็นได้ชัดจากตอนที่เจ้าสู้กับเด็กหญิงสวมหน้ากากนั่น"
L19_1.m_Talk_THA = L20_1
L20_1 = "Điều đó đã quá rõ ràng khi cô chiến đấu với cô gái đeo mặt nạ đó."
L19_1.m_Talk_VTN = L20_1
L20_1 = "你和那个戴面具的丫头交手时我就已经确定了。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Das war schon offensichtlich, als du gegen dieses maskierte Mädchen gekämpft hast."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Ta performance face à cette guerrière masquée est sans appel."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "NANAHARA2_ACT1_INTERLUDE3@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5100108
L20_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L20_1.m_Pos = "C"
L21_1 = "넌 명부신께서 예견한 무사가 아니야."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "お主は冥府の神が予言した武士ではない。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "You are not the warrior that the Nether God predicted."
L20_1.m_Talk_ENG = L21_1
L21_1 = "你不是冥府神預言的武士。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เจ้าไม่ใช่นักรบที่ยมราชทำนายไว้"
L20_1.m_Talk_THA = L21_1
L21_1 = "Cô không phải chiến binh mà Thần Âm Ty đã tiên đoán."
L20_1.m_Talk_VTN = L21_1
L21_1 = "你不是冥神预言的武士。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Du bist nicht die Kriegerin, die der Gott des Jenseits prophezeit hat."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Tu n'es pas la guerrière que le Dieu du Néant attendait."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "NANAHARA2_ACT1_INTERLUDE3@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5100108
L21_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_HATE"
L22_1 = "CHIFUYU_NANA_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "그렇게 말씀하시는 이유는……. 제가 그자에게 패배했기 때문입니까?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そうおっしゃる理由は……私があの者に負けたからですか？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Is it... because I lost against her?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "您之所以會這麼說……是因為我打輸她嗎？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เป็นเพราะ... ข้าแพ้นางหรือคะ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Có phải... bởi vì tôi đã thua cô ấy không?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "您之所以这样说……是因为我败给了她吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ist es ... weil ich gegen dieses maskierte Mädchen verloren habe?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Vous dites ça... parce que j'ai perdu, n'est-ce pas ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NANAHARA2_ACT1_INTERLUDE3@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5100108
L22_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_IDLE"
L22_1.m_Face = L23_1
L22_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "두려워 할 죽음이 없다는 건 비단 자기 목숨만을 두고 하는 얘기가 아니다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "恐れるべき死がないというのは、己の命のみを指して言っているのではないのじゃ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "To be unafraid of death goes beyond your own life."
L22_1.m_Talk_ENG = L23_1
L23_1 = "所謂無懼死亡，並不單指犧牲自己的性命。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "การไม่กลัวความตายไม่ได้หมายถึงแค่ชีวิตตัวเองนะ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Không sợ hãi trước cái chết, có ý nghĩa lớn hơn cả mạng sống của chính mình."
L22_1.m_Talk_VTN = L23_1
L23_1 = "不畏惧死亡，说的不仅仅是自己的性命。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Keine Angst vor dem Tod zu haben geht über das eigene Leben hinaus."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ne pas craindre la mort, c'est une considération qui s'étend au-delà de sa propre vie."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NANAHARA2_ACT1_INTERLUDE3@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 5100108
L23_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_LAUGH"
L23_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "너도 네 목숨만큼 중히 여기는 것이 하나쯤은 있지 않느냐?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "お主とてその命と同じくらい大切にしているものが一つくらいはあるじゃろう？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Don’t you have something dear to you, enough to sacrifice your own life for?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "你的生命中有一個如自己性命般重要的人吧？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แต่เจ้ามีสิ่งอันเป็นที่รักยิ่ง จนสามารถสละชีวิตตัวเองให้ได้หรือไม่?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cô không có thứ gì đó thân yêu, đủ để cô dám hy sinh mạng sống của mình sao?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "你有一样东西比自己的命还重要吧？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Gibt es nichts, wofür du bereit wärst, dein eigenes Leben zu opfern?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "N'y a-t-il rien de précieux à tes yeux ? De précieux au point que tu veuilles offrir ta vie pour le protéger ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
