L25_1 = "CHIFUYU_NANA_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "목숨만큼…… 중요한 것?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "命と同じくらい……大切なもの？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Something dear...?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "如自己性命般……重要的人？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "สิ่งอันเป็นที่รักยิ่งหรือคะ...?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cái gì đó thân yêu ...?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "比我的命……还重要的东西？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Etwas, wofür ich mein eigenes Leben opfern würde ...?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "De précieux... à mes yeux ?"
L24_1.m_Talk_FRA = L25_1
