L27_1.m_StartFXSoundName = L28_1
L27_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L28_1 = "그러니 난 이만 다른 마땅한 주인이 있는지 찾으러 가봐야겠구나."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "わしは他に適当な者がいないか探しに行くことにするかのう。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I must get going now. I need to find another worthy candidate."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我現在要去找找有沒有其他合適的人選。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ไปก่อนนะ ข้าต้องไปหาผู้เหมาะสมคนอื่นอีก"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi phải đi ngay bây giờ. Tôi cần tìm một ứng viên xứng đáng khác."
L27_1.m_Talk_VTN = L28_1
L28_1 = "我现在要去找找有没有其他符合条件的人选了。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich muss jetzt los. Ich muss einen anderen würdigen Kandidaten finden."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Je dois y aller, maintenant. Il faut que je trouve un autre candidat."
L27_1.m_Talk_FRA = L28_1
