L29_1 = "... Oh."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "NANAHARA2_ACT1_INTERLUDE3@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5100108
L29_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "CHIFUYU_NANA_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "이 명부검은 가져가지 않으시는 겁니까?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "この冥府剣は持っていかれないのですか？"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Are you not going to take this sword back?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "這把冥府劍您沒有要帶走嗎？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ท่านคงไม่ได้จะเอาดาบนี้คืนใช่ไหมคะ?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Cô sẽ không lấy lại thanh kiếm này sao?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "这把冥剑您不拿走吗？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Werden Sie dieses Schwert nicht mitnehmen?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Vous ne prenez pas l'épée ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "NANAHARA2_ACT1_INTERLUDE3@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5100108
L30_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_DESPAIR"
L30_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "들고 다니기 귀찮다. 네 녀석이 잠시 맡아 두거라."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "持ち歩くのが面倒なんじゃ。お主がしばし預かっておけ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "It’s a hassle to carry it around all the time. You take care of it for the mean time."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我帶著它礙事，就先交給你保管吧。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แบกไปนั่นมานี่ตลอดเวลาก็วุ่นวายเปล่าๆ ตอนนี้ก็ฝากเจ้าดูด้วยแล้วกัน"
L30_1.m_Talk_THA = L31_1
L31_1 = "Thật rắc rối khi mang nó đi khắp nơi. Tạm thời cô hãy bảo quản nó giúp tôi đi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "拿着它很碍事，暂时先交给你保管吧。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Es ist mühsam, es ständig herumzutragen. Du kannst dich vorübergehend darum kümmern."
L30_1.m_Talk_DEU = L31_1
L31_1 = "C'est une vraie plaie à transporter, ce machin. Tu peux la garder en attendant."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NANAHARA2_ACT1_INTERLUDE3@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5100108
L31_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_IDLE"
L31_1.m_Face = L32_1
L31_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "그 검은 베지 못할 뿐, 쓰는 데엔 문제없을 거다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "その刀は斬ることができないだけで、使うには問題なかろう。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "You won’t have any problems using it, apart from slashing."
L31_1.m_Talk_ENG = L32_1
L32_1 = "它只是沒辦法斬殺而已，起碼還是堪用的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ถ้าไม่เอาไปฟันอะไร เจ้าก็คงใช้มันได้ไม่มีปัญหา"
L31_1.m_Talk_THA = L32_1
L32_1 = "Cô sẽ không gặp vấn đề gì khi sử dụng nó, ngoài việc chém."
L31_1.m_Talk_VTN = L32_1
L32_1 = "这把剑只是不方便砍人，临时用应该没问题。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Es ist aber so, dass das Schwert nichts zerschneiden kann, daher sollte es kein Problem sein, es zu benutzen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Tu ne pourras rien couper avec, mais elle t'aidera quand même pour d'autres choses."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "NANAHARA2_ACT1_INTERLUDE3@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5100108
L32_1.m_CutScenStrID = "NANAHARA2_ACT1_INTERLUDE3"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "DRAGON_NANAHARA_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "말인 즉, 공격을 막으려다 부러질 일은 없다는 게지."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "つまり、攻撃を止めようとして折れることはないということじゃ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "In other words, it will never break trying to block something."
L32_1.m_Talk_ENG = L33_1
L33_1 = "意思就是，在抵擋別人的攻擊時也不會斷掉。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "พูดอีกอย่างคือ เอาไปป้องกันอะไรก็ไม่มีวันหักหรอก"
L32_1.m_Talk_THA = L33_1
L33_1 = "Nói cách khác, nó sẽ không bao giờ bị hỏng khi cố gắng chặn thứ gì đó."
L32_1.m_Talk_VTN = L33_1
L33_1 = "换言之，用来抵挡攻击也不会断掉。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das bedeutet, dass es beim Versuch, einen Angriff abzuwehren, nicht kaputt geht."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Par exemple, tu peux t'en servir pour parer des attaques sans craindre de la voir se briser."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
